def load_any(path: Path) -> bytes:
    """Read wav directly; decode anything else.

    Phone recorders produce m4a, so this is the common case. PyAV is tried
    before an ffmpeg subprocess because it bundles its own codecs - installing
    ffmpeg separately meant a 30 MB download over a link running at 25 KB/s.
    """
    if path.suffix.lower() == ".wav":
        frames, rate, channels, width = au.read_wav(path)
        return au.normalize(frames, rate, channels, width)

    try:
        import av

        with av.open(str(path)) as container:
            stream = container.streams.audio[0]
            resampler = av.AudioResampler(format="s16", layout="mono", rate=au.TARGET_RATE)
            chunks = []
            for frame in container.decode(stream):
                for resampled in resampler.resample(frame):
                    chunks.append(bytes(resampled.planes[0]))
            for resampled in resampler.resample(None):
                chunks.append(bytes(resampled.planes[0]))
        if chunks:
            return b"".join(chunks)
        print("PyAV 解出空音频，改试 ffmpeg", file=sys.stderr)
    except ImportError:
        pass
    except Exception as exc:  # noqa: BLE001 - fall through to ffmpeg.
        print(f"PyAV 解码失败（{type(exc).__name__}: {exc}），改试 ffmpeg", file=sys.stderr)

    for exe in ("ffmpeg", r"C:\ffmpeg\bin\ffmpeg.exe"):
        try:
            result = subprocess.run(
                [exe, "-i", str(path), "-f", "wav", "-ar", str(au.TARGET_RATE),
                 "-ac", "1", "-acodec", "pcm_s16le", "-"],
                capture_output=True, timeout=300, check=True,
            )
            import io

            with wave.open(io.BytesIO(result.stdout), "rb") as handle:
                return handle.readframes(handle.getnframes())
        except FileNotFoundError:
            continue
        except subprocess.CalledProcessError as exc:
            print(f"ffmpeg 解码失败: {exc.stderr[-300:].decode('utf-8', 'ignore')}", file=sys.stderr)
            raise SystemExit(2)
    print(f"无法解码 {path.suffix} 文件：PyAV 和 ffmpeg 都不可用。", file=sys.stderr)
    print("装法: pip install av   或把 wav 格式的录音给我。", file=sys.stderr)
    raise SystemExit(2)

